// Parity between the engine (+ accounting) and the generated mechanism strategy files, through injectable
// copies: every trade (entry and exit session, minute, price, reason, profit, interest), the summary totals,
// both drawdowns and every daily mark.
//   npm run recovery-eligibility -- parity [--vectors N]
// Each copy is the generated file with a fixed list of substitutions, each required to match exactly once:
// an exported `injected` object read at call time, the session list, every hard-coded constant (matched by
// name and a numeric literal) and the arming guard honouring a common first eligible session. With nothing
// injected a copy behaves exactly as its source. Copies go to src/recovery-eligibility/generated/ (git-ignored).
import { createHash } from 'node:crypto';
import path from 'node:path';
import fs from 'fs-extra';
import type { BacktestPosition, MarketSession } from '#types';
import { type Dataset, ReferenceHighCache, fixtureDataset } from '../four-family/data.ts';
import { randomScenario } from '../four-family/tests/fixtures.ts';
import { Rng } from '../optimizer/rng.ts';
import { replay } from '../trailing-buy-variants/accounting.ts';
import { type Data, protocol, stageDir, writeJson } from './context.ts';
import { type StopFill, simulate } from './engine.ts';
import {
  type Family,
  type IntParams,
  families,
  familySpecs,
  genomeToParams,
  gridSize,
  specs,
  toParams
} from './families.ts';
import { type GeneratedFile, generatedFiles } from './generate.ts';

export const tolerance = 1e-6;
export const generatedDir = 'src/recovery-eligibility/generated';

export const injectableConstants = [
  'tickWindowSize',
  'trailingStopPercentage',
  'maximumHoldDays',
  'marginInterestRate',
  'latchDepth',
  'troughRecovery',
  'troughRetrace',
  'episodeReset',
  'resetPolicy',
  'episodeExpiry',
  'anchorPolicy',
  'shallowDepth',
  'shallowRebound',
  'pullback',
  'continuationWindow'
] as const;

export type InjectableConstant = (typeof injectableConstants)[number];

const injectedDeclaration = `import fs from 'fs-extra';

// Generated by src/recovery-eligibility/parity.ts from the strategy file: parameter injection for parity with
// the engine. Do not edit; regenerate with \`npm run recovery-eligibility -- parity\`.
export const injected: {
  sessions?: MarketSession[];
  armStart?: number;
${injectableConstants.map((name) => `  ${name}?: number;`).join('\n')}
} = {};`;

export const sha256 = (text: string | Buffer) => createHash('sha256').update(text).digest('hex');

export const generateCopy = async (spec: GeneratedFile) => {
  const source = await fs.readFile(spec.file, 'utf8');
  let copy = source;
  const once = (from: string, to: string, label: string) => {
    const matches = copy.split(from).length - 1;

    if (matches !== 1) {
      throw new Error(`${spec.file}: expected exactly one ${label}, found ${matches}`);
    }

    copy = copy.replace(from, () => to);
  };
  const constants: string[] = [];

  once("import fs from 'fs-extra';", injectedDeclaration, 'fs import');
  once(
    'const allSessions = groupMarketSessions(await loadCsvMinuteBacktestData(symbol, file));',
    'const allSessions = injected.sessions ?? groupMarketSessions(await loadCsvMinuteBacktestData(symbol, file));',
    'session load'
  );
  once(
    'if (index < tickWindowSize) {',
    'if (index < Math.max(tickWindowSize, injected.armStart ?? 0)) {',
    'arming guard'
  );

  for (const name of injectableConstants) {
    const pattern = new RegExp(`const ${name}(: number)? = ([0-9.]+);`, 'g');
    const matches = copy.match(pattern) ?? [];

    if (matches.length > 1) {
      throw new Error(`${spec.file}: ${name} is declared ${matches.length} times`);
    }

    if (matches.length === 1) {
      copy = copy.replace(
        pattern,
        (_match, annotation: string | undefined, literal: string) =>
          `const ${name}${annotation ?? ''} = injected.${name} ?? ${literal};`
      );
      constants.push(name);
    }
  }

  const target = path.join(generatedDir, path.basename(spec.file));

  await fs.ensureDir(generatedDir);
  await fs.writeFile(path.join(generatedDir, '.gitignore'), '*\n');
  await fs.writeFile(target, copy);

  return { spec, sourceHash: sha256(source), target, constants };
};

// The constants a generated file declares, read from its text.
export const fileDefaults = async (spec: GeneratedFile): Promise<IntParams> => {
  const text = await fs.readFile(spec.file, 'utf8');
  const literal = (name: string, pattern = `const ${name}(?:: number)? = ([0-9.]+);`) => {
    const match = text.match(new RegExp(pattern));

    return match ? Number(match[1]) : undefined;
  };
  const optionDefault = (name: string) => literal(name, `const ${name} = ${name}Option \\?\\? ([0-9.]+);`);
  const family = families[spec.key]!;
  const params: IntParams = {};
  const toInt = (key: string, value: number | undefined) =>
    value === undefined
      ? undefined
      : specs[key as keyof typeof specs]!.unit === 'tenths of a percentage point'
        ? Math.round(value * 1000)
        : value;

  for (const key of family.paramKeys) {
    const raw = ['targetPercentChange', 'trailingBuyPercentage', 'intradayLossBuffer'].includes(key)
      ? optionDefault(key)
      : literal(key);
    const value = toInt(key, raw);

    if (value === undefined) {
      throw new Error(`${spec.file}: could not read ${key}`);
    }

    params[key] = value;
  }

  params.anchorPolicy = literal('anchorPolicy') ?? 0;

  return params;
};

export interface ParityCase {
  name: string;
  spec: GeneratedFile;
  stopFill: StopFill;
  params: IntParams;
  inject: boolean;
  armStart?: number;
  marginInterestRate: number;
}

interface CopyModule {
  injected: Record<string, unknown>;
  runAllIn: (options: Record<string, unknown>) => Promise<{
    positions: BacktestPosition[];
    entryFills: Map<
      BacktestPosition,
      { time: number; price: number; execution: string; decisionTime: number; setupKind: string; anchorHigh: number }
    >;
    exitFills: Map<BacktestPosition, { time: number; price: number; reason: string }>;
  }>;
}

const modules = new Map<string, CopyModule>();

const loadCopy = async (target: string): Promise<CopyModule> => {
  let module = modules.get(target);

  if (!module) {
    module = (await import(path.resolve(target))) as CopyModule;
    modules.set(target, module);
  }

  return module;
};

const nearly = (a: number, b: number) => Math.abs(a - b) <= tolerance * Math.max(1, Math.abs(a), Math.abs(b));

export const runParityCase = async (ds: Dataset, sessions: MarketSession[], target: string, parityCase: ParityCase) => {
  const module = await loadCopy(target);
  const family = families[parityCase.spec.key]!;
  const params = toParams(family, parityCase.params);
  const { injected } = module;

  for (const key of Object.keys(injected)) {
    delete injected[key];
  }

  injected.sessions = sessions;

  if (parityCase.inject) {
    injected.armStart = parityCase.armStart;
    injected.tickWindowSize = params.tickWindowSize;
    injected.trailingStopPercentage = params.trailingStopPercentage;
    injected.maximumHoldDays = params.maximumHoldDays;
    injected.marginInterestRate = parityCase.marginInterestRate;

    for (const key of [
      'latchDepth',
      'troughRecovery',
      'troughRetrace',
      'episodeReset',
      'resetPolicy',
      'episodeExpiry',
      'anchorPolicy',
      'shallowDepth',
      'shallowRebound',
      'pullback',
      'continuationWindow'
    ] as const) {
      if (family.paramKeys.includes(key) || key === 'anchorPolicy') {
        const value = params[key];

        if (Number.isFinite(value)) {
          injected[key] = value;
        }
      }
    }
  }

  const outDir = path.join(generatedDir, 'parity-out', parityCase.spec.key);
  const info = console.info;

  console.info = () => {};

  let result: Awaited<ReturnType<CopyModule['runAllIn']>>;

  try {
    result = await module.runAllIn({
      symbol: 'VGT',
      outDir,
      stopFill: parityCase.stopFill,
      ...(parityCase.inject
        ? {
            targetPercentChange: params.targetPercentChange,
            trailingBuyPercentage: params.trailingBuyPercentage,
            intradayLossBuffer: params.intradayLossBuffer
          }
        : {})
    });
  } finally {
    console.info = info;
  }

  const summary = JSON.parse(await fs.readFile(path.join(outDir, 'summary.json'), 'utf8')) as Record<string, number>;
  const dailyText = await fs.readFile(path.join(outDir, 'daily.csv'), 'utf8');
  const dailyMarks = dailyText
    .trim()
    .split('\n')
    .slice(1)
    .map((line) => Number(line.split(',')[4]));

  // The engine on the same settings.
  const armStart = parityCase.inject
    ? Math.max(params.tickWindowSize, parityCase.armStart ?? 0)
    : params.tickWindowSize;
  const highs = new ReferenceHighCache(ds).get(params.tickWindowSize);
  const engine = simulate(ds, highs, family.flags, params, {
    stopFill: parityCase.stopFill,
    marginInterestRate: parityCase.marginInterestRate,
    investment: 100000,
    firstIndex: 0,
    armStart,
    endIndex: ds.sessionCount - 1
  });
  const accounting = replay(ds, engine.trades, {
    firstIndex: 0,
    endIndex: ds.sessionCount - 1,
    marginInterestRate: parityCase.marginInterestRate,
    dailyMarks: true
  });
  const differences: string[] = [];
  const check = (label: string, a: number | string | boolean, b: number | string | boolean) => {
    const same = typeof a === 'number' && typeof b === 'number' ? nearly(a, b) : a === b;

    if (!same) {
      differences.push(`${label}: file ${String(a)} vs engine ${String(b)}`);
    }
  };

  check('trade count', result.positions.length, engine.trades.length);

  result.positions.forEach((position, index) => {
    const trade = engine.trades[index];
    const outcome = accounting.outcomes[index];

    if (!trade || !outcome) {
      return;
    }

    const entryFill = result.entryFills.get(position)!;
    const exitFill = result.exitFills.get(position);

    check(`trade ${index + 1} entry session`, position.entryTimestamp, trade.entryTimestamp);
    check(`trade ${index + 1} entry time`, entryFill.time, trade.entryTime);
    check(`trade ${index + 1} entry price`, position.entryPrice, trade.entryPrice);
    check(`trade ${index + 1} entry execution`, entryFill.execution, trade.entryExecution);
    check(`trade ${index + 1} decision time`, entryFill.decisionTime, trade.decisionTime);
    check(`trade ${index + 1} kind`, entryFill.setupKind, trade.kind);
    check(`trade ${index + 1} anchor`, entryFill.anchorHigh, trade.anchorHigh);
    check(`trade ${index + 1} open`, position.isOpen, trade.exitIndex < 0);

    if (!position.isOpen) {
      check(`trade ${index + 1} exit session`, position.exitTimestamp ?? NaN, ds.sTime[trade.exitIndex]!);
      check(`trade ${index + 1} exit time`, exitFill?.time ?? NaN, trade.exitTime);
      check(`trade ${index + 1} exit price`, position.exitPrice ?? NaN, trade.exitPrice);
      check(`trade ${index + 1} reason`, exitFill?.reason ?? '', trade.reason);
      check(`trade ${index + 1} profit`, position.profit ?? NaN, outcome.profit);
      check(`trade ${index + 1} interest`, position.interest ?? NaN, outcome.interest);
    }
  });

  check('net profit', summary.netProfit!, accounting.netProfit);
  check('realized profit', summary.realizedProfit!, accounting.realizedProfit);
  check('unrealized profit', summary.unrealizedProfit!, accounting.unrealizedProfit);
  check('margin interest', summary.marginInterest!, accounting.closedInterest + accounting.accruedInterest);
  check('daily drawdown', summary.maximumDrawdown!, accounting.dailyDrawdown.maximum);
  check('minute drawdown', summary.minuteMaximumDrawdown!, accounting.minuteDrawdown.maximum);
  check('setup activations', summary.setupActivations!, engine.counts.setupActivations);
  check('daily mark count', dailyMarks.length, ds.sessionCount);

  let markDifferences = 0;

  dailyMarks.forEach((mark, index) => {
    if (!nearly(mark, accounting.dailyMarks![index]!)) {
      markDifferences++;
    }
  });

  if (markDifferences > 0) {
    differences.push(`${markDifferences} daily marks differ`);
  }

  return { name: parityCase.name, trades: engine.trades.length, net: accounting.netProfit, differences };
};

export const randomLatticeParams = (rng: Rng, family: Family): IntParams =>
  genomeToParams(
    family,
    familySpecs(family).map((spec) => rng.int(gridSize(spec)))
  );

export const runParity = async ({ ds, sessions }: Data, args: string[]) => {
  const vectorsArgument = args.indexOf('--vectors');
  const vectors = vectorsArgument >= 0 ? Number(args[vectorsArgument + 1]) : 40;
  const syntheticArgument = args.indexOf('--synthetic');
  const synthetic = syntheticArgument >= 0 ? Number(args[syntheticArgument + 1]) : 60;
  const rng = Rng.from('recovery-eligibility', 'parity');
  const report: {
    file: string;
    sourceHash: string;
    cases: { name: string; trades: number; net: number; differences: string[] }[];
  }[] = [];
  let failures = 0;

  for (const spec of generatedFiles) {
    const { target, sourceHash } = await generateCopy(spec);
    const family = families[spec.key]!;
    const defaults = await fileDefaults(spec);
    const cases: ParityCase[] = [];

    for (const stopFill of ['stop', 'next-open'] as const) {
      cases.push({
        name: `${spec.key} file defaults, ${stopFill}, whole file`,
        spec,
        stopFill,
        params: defaults,
        inject: false,
        marginInterestRate: 0.11
      });
    }

    for (let index = 0; index < vectors; index++) {
      const params = randomLatticeParams(rng, family);

      params.anchorPolicy = rng.int(2);
      cases.push({
        name: `${spec.key} lattice vector ${index + 1}`,
        spec,
        stopFill: rng.next() < 0.5 ? 'stop' : 'next-open',
        params,
        inject: true,
        armStart: rng.next() < 0.5 ? protocol.eligibilityIndex : 180,
        marginInterestRate: [0.08, 0.11, 0.14][rng.int(3)]!
      });
    }

    const results: { name: string; trades: number; net: number; differences: string[] }[] = [];

    for (const parityCase of cases) {
      const result = await runParityCase(ds, sessions, target, parityCase);

      results.push(result);

      if (result.differences.length > 0) {
        failures++;
        console.info(`✖ ${result.name}: ${result.differences.slice(0, 5).join('; ')}`);
      }
    }

    // Synthetic scenarios: random minute data with early closes, missing minutes and closing prints.
    for (let index = 0; index < synthetic; index++) {
      const scenarioSessions = randomScenario(`recovery-parity-${spec.key}-${index}`, 40 + rng.int(80));
      const scenario = fixtureDataset(scenarioSessions);
      const params = randomLatticeParams(rng, family);

      params.tickWindowSize = 5 + rng.int(15);
      params.anchorPolicy = rng.int(2);

      if (family.paramKeys.includes('episodeExpiry')) {
        params.episodeExpiry = 5 + rng.int(60);
      }

      if (family.paramKeys.includes('continuationWindow')) {
        params.continuationWindow = 3 + rng.int(40);
      }

      const result = await runParityCase(scenario, scenarioSessions, target, {
        name: `${spec.key} synthetic scenario ${index + 1}`,
        spec,
        stopFill: rng.next() < 0.5 ? 'stop' : 'next-open',
        params,
        inject: true,
        armStart: params.tickWindowSize + rng.int(5),
        marginInterestRate: [0.08, 0.11, 0.14][rng.int(3)]!
      });

      results.push(result);

      if (result.differences.length > 0) {
        failures++;
        console.info(`✖ ${result.name}: ${result.differences.slice(0, 5).join('; ')}`);
      }
    }

    console.info(
      `${spec.file}: ${results.length - results.filter((result) => result.differences.length > 0).length}/${results.length} cases identical (${results.reduce((total, result) => total + result.trades, 0)} trades compared)`
    );
    report.push({ file: spec.file, sourceHash, cases: results });
  }

  await writeJson(stageDir('parity', 'parity.json'), { datasetId: ds.id, vectors, synthetic, failures, report });
  console.info(`Wrote ${stageDir('parity', 'parity.json')}; ${failures} failing cases`);
};
